// ===== duellines.js (v0.7.7): every wayfarer who challenges you speaks in their own voice =====
// Before this, a road duel used one line per class, so every fighter (or every mage) said the same thing. Now each of the 92
// wayfarers has their own lines, keyed by hero id. Keys:
//   o  the opening challenge on the road            m  a short shout at half health (the battle banner, keep it under 27 letters)
//   w  they lose the duel and wait at a tavern      l  the party loses to them
//   f  the party runs from the duel                 d  the party declines the duel
//   r  to their own rival, before the personal quest fight (the hero is in your party)
//   rw after the rival falls (shown on the rewards screen)
// Legends (kaevan, nikaris, jaeson) and Vaelith never duel on the road: their o/w/l/f lines fit their own events.
// A value may be an array of variants: one is picked from the journey seed (never the game RNG, so the Daily Trial stays the same).
// DUEL_REPLY['challenger>partyHero'] is said by a party hero with a bond history (skills.js BONDS) with the challenger.
// DUEL_GUILD gives the Guild Hall recruitment challenge heroes a line on the board (g) and when they join (j).
// Any hero without lines (a future wayfarer) gets dlFallback: built from name, class, element and trait, so it is still their own.
const DUEL_LINES={
 brann:{o:"I used to beat iron flat for a living. Let us see if you ring true or crack.",m:"Now the forge is hot!",w:"Ha! You've a good temper on you, like proper steel. I'll be at the tavern, warming a stool.",l:"Back to the anvil with you. Come find me when you've been folded a few more times.",f:"Running from the heat? Smart. The forge always wins in the end.",d:"Bah. Cold iron never learned anything. Off with you, then.",r:"You broke my first blade. I've forged a better one, and you'll feel every hammer stroke.",rw:"There. That's the last of that old grudge. I'll sleep sound tonight."},
 mira:{o:"The tide told me someone worth testing would come this way. Shall we see if it was right?",m:"The tide is turning.",w:"The tide was right about you. Look for me at the tavern, reading the foam in my cup.",l:"The water always finds the low ground. Rest, and come back at high tide.",f:"Ebbing away already? The sea does that too. It always returns.",d:"As you like. The tide will bring us together again.",r:"You swallowed my focus whole. I want it back, and the sea wants you gone.",rw:"My focus, still cold from the deep. The shallows will sing tonight."},
 sable:{o:"You did not see me until now. That is your first lesson. Here is your second.",m:"Still watching? Good.",w:"You saw me coming. Few do. I will be in a tavern corner, if you remember to look.",l:"Do not worry. Nobody will remember this but me.",f:"Gone? Now you are learning my trade.",d:"Then this meeting never happened. You will barely recall my face.",r:"You are holding what I am owed. I always collect, and I collect in the dark.",rw:"Paid in full. Now I can go back to being forgotten."},
 tess:{o:"I've carried letters through worse than you. One bout, and I get the first shot. I always do.",m:"Wind's at my back now.",w:"Well, that letter never reached its address. You win. I'll be at the tavern, sorting arrows.",l:"Delivered. Sign here, and maybe practise your footwork.",f:"Off you go! Faster than my old horse, I'll give you that.",d:"No? Fair enough. I've a route to run anyway.",r:"I missed you once, years back. I've not missed a thing since, and I won't start with you.",rw:"Second shot, straight and true. That's the last loose end on my route."},
 oren:{o:"I have kept a gate for twenty years. Today the gate is me. Try to get past.",m:"The wall holds.",w:"You found the way through. Nobody has in years. I will keep watch by the tavern door for you.",l:"The gate stays shut. Rest your arms and try again another day.",f:"Retreat. I never learned the word, but you say it well.",d:"Then pass in peace. The gate was never closed to friends.",r:"I swore you would not reach another village. I keep my oaths the way I keep my gates.",rw:"The oath is kept. The road behind me is safe again."},
 lumen:{o:"I am small, I know. But my lamp has never gone out, and I would like to see how bright you burn.",m:"My lamp is still lit!",w:"You shine brighter than I thought. I will save you a seat by the lanterns at the tavern.",l:"There now, nothing broken. Let me light your way back to town.",f:"Mind the dark on your way! I will keep the lamp lit for you.",d:"That is alright. A lamp keeper learns patience early.",r:"The first lamp keepers made that relic. You are not fit to hold their light.",rw:"It still glows. Oh, it still glows. My master would weep."},
 kael:{o:"The thunder said I would meet a worthy fight today. The thunder is never wrong. Mostly.",m:"Hear it? BOOM.",w:"The thunder says you won. Fine, it gets the last word. Find me at the tavern when the storm calls.",l:"The sky laughed at you. Do not worry, it laughs at me too.",f:"Running from the storm? The storm finds everyone.",d:"The thunder is disappointed. I am a little disappointed. Go on.",r:"You shattered my first blade under a clear sky. Today the sky is on my side.",rw:"Hear that rumble? The storm is cheering."},
 pip:{o:"Right, a quick bout! Winner buys supper, loser explains it to the harbour master. Deal?",m:"Slippery as an eel, me!",w:"Fine, fine, you got me fair. I'll be at the tavern. Bring coin, I've expensive tastes.",l:"Don't look so glum. Happens to the best of us, usually because of me.",f:"Ha! Running's the first thing they teach you on the docks.",d:"Your loss. I'd have let you win. Probably.",r:"You've been sitting on my payment like a fat gull on a crate. Shove over.",rw:"Debt settled and a bit left over. Don't tell the harbour master."},
 wren:{o:"The old trees whispered of you. Stand your ground, and let us see if your roots go deep.",m:"The roots hold me fast.",w:"Your roots run deeper than mine. I will rest my antlers in the tavern until you call.",l:"The forest floor is soft. Lie there a while and listen to it.",f:"Even deer know when to bolt. No shame in it.",d:"Then go gently. The trees will remember you passed.",r:"I loosed at you once among the old roots, and missed. The roots have waited as long as I have.",rw:"The arrow found its mark. The old trees can rest."},
 gilda:{o:"Every song I sing ends in a fire. Care to be the next verse?",m:"Here comes the chorus!",w:"What a finale! I'll sing it at the tavern tonight. Come hear yourselves be heroes.",l:"Ah, the tragic verse. Don't fret, those always get the best applause.",f:"Exit, pursued by a dwarf! That's going in the song.",d:"No duel? Then I'll write you as cowards. Kindly, mind.",r:"One more verse for the ballad, and it ends with you in flames.",rw:"And the last line burns bright. The ballad is finished!"},
 fenn:{o:"I have catalogued nine thousand snowflakes and not one good fighter. Kindly be entry number one.",m:"Fascinating. Noted.",w:"Entry one, filed under remarkable. Find me at the tavern, the gnome with the ledger.",l:"Defeated, but most instructive. I took notes for you.",f:"Retreating. A sensible entry. I shall file it kindly.",d:"A pity. My ledger had a clean page ready.",r:"You swallowed my focus like a common pebble. I catalogue everything, and now I catalogue your end.",rw:"Focus recovered, slightly frostbitten. Filed and finished."},
 halden:{o:"Thirty winters on the frost wall and nobody has flanked me. Come. Try.",m:"Cold steadies the hand.",w:"Well. There is a first time for everything. I'll be by the tavern fire when you want me.",l:"Up. Shake off the snow. The wall teaches slowly.",f:"Pulling back in good order. That I can respect.",d:"Wise, perhaps. The wall does not chase.",r:"I swore on the frost wall that you would get no further. I meant every word.",rw:"Oath kept. The wall can sleep."},
 pomona:{o:"Oh, you look healthy! Let's fix that, then I'll fix it back. Fae custom, you understand.",m:"Just a little breeze!",w:"Well done, my apples! Off to the tavern with me, I'll have a poultice and a pie waiting.",l:"Hush now, only bruises. I've a salve that smells of blossom.",f:"Off on the wind! I quite approve.",d:"Another time, sweetling. The orchard isn't going anywhere.",r:"That relic belongs to the lamp keepers, you greedy thing, and I'm taking it home on the wind.",rw:"Got it! The orchard will bloom twice this year, I'm sure of it."},
 taro:{o:"I had an idea this morning. The idea was you. Let us find out if it was a good one.",m:"Another idea strikes!",w:"A good idea after all, and a humbling one. I will meditate at the tavern until you come.",l:"Ah. That was a loud idea. Breathe, and rise when you are ready.",f:"Leaving. Perhaps that is your idea. A fine one.",d:"Then the idea waits. Ideas are patient, unlike me.",r:"Master, I am here. This creature took you, and today I finish the lesson.",rw:"The lesson is done, master. I listened."},
 cass:{o:"I read you from the ridge before you saw me. Now let me read you up close.",m:"Wind's turning my way.",w:"You read me better than I read you. I'll wait for you in a tavern, by the window.",l:"You swung before you looked. Look first, next time.",f:"Fast feet. Shame about the rest.",d:"Smart. You read the fight and passed on it.",r:"You broke my first blade on a cliff edge. Today you learn I have no fear of falling.",rw:"That's the old score cleared. The wind feels lighter."},
 shen:{o:"I bathe in ice each morning. I doubt you will sting much more. Shall we see?",m:"Hardly a chill.",w:"That one I felt. Thank you. I will be at the tavern, sitting very still.",l:"Rest in the snow a while. It clears the mind.",f:"Cold feet. Understandable.",d:"Then go in calm. The ice is patient.",r:"Master, I have bathed in colder water than this beast's breath. I am ready to finish your lesson.",rw:"The lesson is complete. The water will feel warm tomorrow."},
 alder:{o:"Tea first, then a friendly bout, then more tea. That is the proper order.",m:"Slow and steady.",w:"A fine match. The kettle is on at the tavern. Come and sit when you are ready.",l:"There, there. Drink this, it is mostly bark.",f:"Off so soon? You did not even finish your tea.",d:"Then we shall skip ahead to the tea.",r:"That relic belongs to the old lamp keepers, and I have grown roots waiting. Give it back.",rw:"Home at last. I shall brew something special."},
 rook:{o:"I've dug a lot of holes. I'd rather not dig one for you. Let's keep this friendly.",m:"Still digging.",w:"You kept going. That's what matters. Find me at the tavern, back table, away from the light.",l:"Up you get. Nobody's going in the ground today.",f:"Leaving? Most folk leave a graveyard quick.",d:"Suit yourselves. I'm not going anywhere. I never do.",r:"You broke my first spade, then my first blade. Time I buried you.",rw:"Buried proper. Rest easy, old grudge."},
 marisol:{o:"I stitch sailors for a living. Let me see how well you hold your seams.",m:"Tide's coming in.",w:"Strong seams, all of you. I'll be at the harbour tavern, mending nets until you come.",l:"Hold still, love. Three stitches and you'll sail again.",f:"Cast off, then! Mind the rocks.",d:"Another tide, perhaps. The sea is in no hurry.",r:"That relic should shine in a harbour shrine, not rot in your hoard.",rw:"Safe now. The harbour lamps will burn a little brighter."},
 vael:{o:"The dark between the stars told me your names. I would like to know if it lied.",m:"The dark leans closer.",w:"It did not lie. How unsettling. I will wait in a tavern, by the coldest window.",l:"Sleep. The stars will still be there. Probably.",f:"You flee the dark. Most people do. It does not mind.",d:"Then I will watch you from a distance. I am good at that.",r:"You swallowed my focus and a whole sky with it. I want my stars back.",rw:"My focus, and the little night inside it. The stars are quiet again."},
 corwin:{o:"A trial of honour, then. Do try not to scuff the armour, I polished it this morning.",m:"Not a scratch, I trust?",w:"Honour satisfied, armour slightly dented. I shall await you in a tavern, polishing.",l:"Rise, friends. Defeat is only a dull spot. Buff it out.",f:"A tactical withdrawal. I shall record it as such.",d:"Very well. The sun will shine on our meeting another day.",r:"By my oath under the dawn, you will not touch another village.",rw:"The oath shines true. Let the villages sleep."},
 kit:{o:"I built a new crossbow and it needs testing. You look sturdy. Hold still, mostly.",m:"Ooh, sparks!",w:"Jammed. Again! You win. I'll be fiddling with it in a tavern, come and find me.",l:"It works! Oh, sorry. But it works!",f:"Run while I reload! Very wise.",d:"Fine. I'll test it on a tree. Trees never dodge.",r:"You're sitting on my payment, and I've built something special just for you.",rw:"Debt collected, crossbow tested. Best day ever."},
 frey:{o:"None pass the glacier gate untested. You are not at the gate, but the rule travels with me.",m:"The ice does not blink.",w:"You found the crack in my guard. I will wait in a tavern for your call.",l:"Rest. The glacier was not built in a day either.",f:"Withdrawing. The gate remembers who turned back.",d:"Then pass, untested. I will keep watching.",r:"I missed you once at the glacier gate. In six thousand years of ice, that was my only miss.",rw:"One arrow, one ending. The gate is whole again."},
 jun:{o:"My fuse is already lit, friend. Let's see who goes off first!",m:"Faster, faster!",w:"Burned right down. That was fun! I'll be in the tavern, the one with the scorch marks.",l:"Boom! Sorry. You'll get me next time. Maybe.",f:"Running from a lit fuse! Sensible, honestly.",d:"Aw. My gloves were already warm.",r:"Master, I'm here. Watch me finish the lesson with my fists on fire.",rw:"Lesson finished, master. Loudly."},
 lark:{o:"The dawn chorus needs a new song. Dance with me a little, and I'll write it.",m:"A rising note!",w:"Oh, that's a lovely refrain! I'll be singing it at the tavern. Come and hear it.",l:"A sad little verse, but a pretty one. Up you get.",f:"Flown off! I'll put a feather in the song for you.",d:"No dance? I'll hum it alone, then.",r:"One more verse, and you are it. Hold still, I'm finding the rhyme.",rw:"The last verse sings itself! The ballad is complete."},
 sorrel:{o:"I have a hypothesis about your mettle. Allow me to test it, with fire.",m:"Every candle at once!",w:"Hypothesis disproven, delightfully. I shall be at the tavern revising my notes.",l:"Hm. Lit a bit too much. Let me fetch some water.",f:"Retreat! A valid result. I'll write it down.",d:"Unscientific of you, but I accept the null result.",r:"You swallowed a focus of fire, you foolish beast. Allow me to retrieve it.",rw:"My focus! A little sooty, perfectly intact. Splendid."},
 sylva:{o:"You walk loud through my marsh. Let's see if you fight any quieter.",m:"Out of the mud!",w:"You're quicker than the bog. I'll wait in a tavern, drying off.",l:"The marsh swallowed you. It does that. Climb out slow.",f:"Splash away. The frogs will tell me where you went.",d:"Go quiet, then. The reeds are listening.",r:"I missed you once in the deep marsh. The mud has kept my arrow warm since.",rw:"Back into the mud with you. The marsh is mine again."},
 gorm:{o:"The mountain rumbles when it is restless. So do I. Come, settle me.",m:"Magma rising.",w:"Ahh. Settled. That felt good. I will be at the tavern, sitting on two stools.",l:"Too much heat for you. Cool off in the stream, little ones.",f:"Running from the eruption. Good instinct.",d:"Then I will rumble alone. It is fine.",r:"Master, the volcano took you, and this thing walks in its ashes. I end it today.",rw:"The mountain is calm. So am I, master."},
 dagna:{o:"Up north we settle things with a quick bout and a warm supper after. You first.",m:"Cold stone, warm heart.",w:"Good work, that. Honest work. Supper's on me at the tavern, come and find me.",l:"Up you get. Nobody leaves my quarry hungry.",f:"Off you trot. I'll save you a bowl anyway.",d:"Fair. Your shoulders look tired anyhow.",r:"You broke the first blade my father ever gave me. I've cut through harder rock than you.",rw:"Done and dusted. Father would be proud."},
 zephra:{o:"The wind and I are rehearsing a piece, and we need a few more players. Take your places!",m:"Crescendo!",w:"Bravo! You stole the show. I'll be conducting at the tavern, come and take a bow.",l:"The piece ends softly. Rest now, we'll rehearse again.",f:"Exit stage left! Lovely timing.",d:"No? The wind will play without you.",r:"You stole the final verse of my symphony. Let the wind take it back.",rw:"The final movement, at last! Hear how the sky applauds."},
 astra:{o:"I hold both halves of the sky. Show me which half you belong to.",m:"Day and night, together.",w:"You belong to both. Rare. I will wait at a tavern, between dusk and dawn.",l:"Even the sun sets. Rest until it rises.",f:"You flee into the light. Or was it the dark?",d:"Then the sky keeps its secret a little longer.",r:"You swallowed my focus and dimmed half the sky. I want my eclipse back.",rw:"Both halves whole again. The sky remembers."},
 ember:{o:"Yes, my hair is on fire. No, I won't put it out. Shall we?",m:"Crackle and burn!",w:"You won before I finished the spell. Rude, but impressive. Find me at the tavern, I'm the bright one.",l:"Oops. Singed eyebrows grow back, mostly.",f:"Run! Honestly, most people do.",d:"Fine, fine. I'll go and set something else alight.",r:"You swallowed my focus and it's still crackling inside you. Let me fetch it out.",rw:"Got it, and only a little scorched. Well, the beast is scorched."},
 vex:{o:"Blink and you miss it. You'll blink. Ready? Too late!",m:"Twice already!",w:"Hah! You caught me. Nobody catches me! I'll be at the tavern, if I sit still that long.",l:"Zip, zap, done. Better luck next time, slow feet.",f:"Ooh, you're fast too! Not as fast as me.",d:"Boring! I'm off. Already gone.",r:"You owe me, and I hit twice before you hear the first. Pay up!",rw:"Paid! Twice! Ha!"},
 isolde:{o:"The tide brought me to you, children. Let us see what it wants me to learn.",m:"A wave of grace.",w:"The tide has spoken for you. I will pray at the tavern until you come.",l:"Rest, child. The waves will carry you home.",f:"Go with the current. It knows the way.",d:"Peace, then. The tide will turn us back together.",r:"That relic was blessed by the first lamp keepers. Your claws do not deserve it.",rw:"Blessed again, and safe. Let the waves be grateful."},
 nyx:{o:"You look warm. I'm going to take some of that. Fair fight, mostly.",m:"Colder now, isn't it?",w:"Hm. You kept your warmth. I'll be in a tavern, curled by the fire you didn't lose.",l:"Shivering? I'll return your purse. Maybe.",f:"Scampering off! Cats do that too.",d:"Your loss. I'd have given you back half.",r:"You're sitting on what I'm owed, and I have very cold claws.",rw:"Collected. And it's warm, too. Lovely."},
 ciro:{o:"Each of my arrows is a little sunrise. Shall I show you dawn?",m:"The sun climbs higher.",w:"You outshone me, gracefully. Seek me at a tavern, at first light.",l:"Rest in the morning glow. You'll rise again.",f:"Fleeing the dawn? It always catches up.",d:"Then I'll keep my sunrise for another sky.",r:"I missed you once at sunset. Today the sun is on the rise.",rw:"A perfect sunrise. My aim is whole again."},
 borga:{o:"I move boulders for a living, and the odd opinion. Let's see if you budge.",m:"Like pushing a mountain.",w:"Well, you budged me. Not many can. I'll be at the tavern, leaning on a wall I haven't moved yet.",l:"Stand up straight. You'll be stronger for it.",f:"Off you march. Keep your backs straight.",d:"Hm. Opinion noted, and moved aside.",r:"You broke my first blade on a boulder. I've moved bigger stones than you.",rw:"Moved. Out of the way, for good."},
 kessa:{o:"I've harpooned thunderheads, sailor. You look a lot easier.",m:"Batten down!",w:"Hah! You've sea legs after all. Look for me at the tavern, cursing the weather.",l:"Overboard you go. Swim back when you're ready.",f:"Abandoning ship? Bold choice.",d:"Pah. Calm seas make dull sailors.",r:"You shattered my first axe in a storm. I've a grudge, and a harpoon.",rw:"Harpooned. The thunderheads are next."},
 solenne:{o:"I prefer to duel at sunrise, so the light is fair to both. This will do. Stand where you like.",m:"The light is still fair.",w:"A fair fight, fairly lost. I'll wait at the tavern, and we shall toast the dawn.",l:"Well fought. The sun will rise for you tomorrow, I promise.",f:"You leave the field with your honour intact. Go.",d:"No fight is better than an unfair one. Farewell.",r:"You shattered my first blade in the dark, coward. Face me in the light.",rw:"Dawn breaks on your grave. Fair and square."},
 deryn:{o:"Lovely drizzle today. Perfect weather for a friendly trial, don't you think?",m:"Just a passing shower.",w:"Well done, all of you. I'll be at the tavern by the window, watching the rain.",l:"There now. Sit in the rain a while. It helps, honestly.",f:"Off you go, before the downpour.",d:"Another day, then. It'll be raining, I expect.",r:"I swore you'd never reach another harbour. I've stood in worse weather than you.",rw:"Oath kept, and it's only drizzling. A perfect day."},
 ignar:{o:"Fire watch, Ashgate post. Every traveller gets inspected. Defend yourselves.",m:"Smoke and steel!",w:"Inspection passed, with soot. Report to the tavern when you need a captain.",l:"Inspection failed. Drink water, eat something, try again.",f:"Evacuating! A good drill. Orderly, too.",d:"Waived, this once. Move along, citizens.",r:"By my oath at the Ashgate watch, you burn no more villages.",rw:"Fire's out. The watch can stand down."},
 isak:{o:"My breath fogs, but my oath does not. Show me you'll still be standing at the end.",m:"The oath holds.",w:"Still standing. That's all I ask. Find me at the tavern, by the hearth.",l:"On your feet when you're able. The harbour waits.",f:"Falling back. Live to stand another day.",d:"Then go carefully across the ice.",r:"I swore on the frozen harbour you'd harm no one else. My oath has not thawed.",rw:"Oath fulfilled. The harbour can thaw now."},
 lorcan:{o:"Stone remembers every blow. Strike me, and let the cathedral hear it.",m:"The stones answer.",w:"The echo is yours. I shall wait in a tavern, as quiet as a crypt.",l:"Rise. The cathedral took a thousand years. You have time.",f:"Your footsteps echo away. Go well.",d:"Then let silence keep us, for now.",r:"On cathedral stone I swore you would stop here. Hear the echo of that vow.",rw:"The vow rings true. Let the stones be still."},
 maelis:{o:"My lantern was lit with a very bad idea. Let me show you how it burns.",m:"The lantern flares!",w:"My lantern dims for you. Rare. I'll wait in a tavern, keeping it low.",l:"Shh. Let the lantern light your way back.",f:"Fleeing my light? Most do. It is a cursed thing.",d:"Wise. My lantern makes a poor companion.",r:"I swore in cursed flame you would never reach another village. My curse keeps its word.",rw:"Oath burned through. The lantern rests."},
 zia:{o:"Today's forecast: scattered sparks, heavy thunder, and one short duel. Shall we?",m:"Storm warning, upgraded!",w:"Forecast revised: you, clear and bright. Find me at the tavern, reading the clouds.",l:"Tomorrow's forecast: sunshine and bandages.",f:"Clearing skies to the east. That's you, running.",d:"Forecast: no duel today. Mild disappointment.",r:"You swallowed my focus, and the forecast for you is very, very stormy.",rw:"Focus restored. Clear skies ahead."},
 cyrene:{o:"My spells arrive in whole weather systems. Wrap up warm, friends.",m:"The blizzard deepens.",w:"You walked through my storm. I'll wait in a tavern where the passes meet.",l:"Sleep under the snow a moment. It is softer than it looks.",f:"Retreat to lower ground. Wise travellers do.",d:"Then may the high passes be kind to you.",r:"You swallowed my focus and the sky with it. Let the blizzard take it back.",rw:"The storm is mine again. Hear it sing."},
 brigid:{o:"The hearth asks a little trial of everyone who passes. Then supper, I promise.",m:"Stoke the fire!",w:"Bless you, that was well done. A warm seat waits for you at the tavern.",l:"Shh, here's a blanket. And a poultice. It'll sting.",f:"Off home to your own hearth? Go safely.",d:"Then may your fire never go out.",r:"That relic belongs on a hearth altar, not in your filthy den. I'm taking it home.",rw:"There, safe by the fire. Let us give thanks."},
 verbena:{o:"My garden asks me to test anyone who walks this way. Gently, of course.",m:"Sunroot and sunshine.",w:"You grow well under pressure. Come find me at the tavern, I'll bring herbs.",l:"There. Chew this leaf. You'll bloom again.",f:"Off you go, little seedlings.",d:"That is alright. Not every seed sprouts at once.",r:"That relic belongs in a shrine garden, where the sun can reach it.",rw:"In the light at last. My garden will bloom all year."},
 hollis:{o:"I work at night, and I have never lost anyone in the dark. Do not make me start.",m:"Easy. Breathe.",w:"Calm hands, all of you. I'll wait at a tavern for dusk, and for you.",l:"Nobody lost. I promise. Let me see that cut.",f:"Go, quietly. I'll watch your backs.",d:"Another night, then. I am always awake.",r:"You hoard the lamp keepers' light in the dark. Not any more.",rw:"Light back where it belongs. Nobody lost tonight."},
 tamsin:{o:"Sorry about this. Truly. One quick bout, and I'll apologise properly after.",m:"Pardon me, sorry!",w:"Oh, well done. Sorry I doubted you. I'll be at the tavern, apologising to the furniture.",l:"I'm so sorry. Really. Do you need a hand up?",f:"Off you go! Sorry for the fright.",d:"Of course, of course. Sorry to have bothered you.",r:"Sorry, truly sorry, but you're sitting on my payment and I need it back.",rw:"There we are. Sorry about all that. Rest well."},
 nettle:{o:"Lucky day for you! Or for me. Let's flip for it, with fire.",m:"Heads I win!",w:"Tails, then. Rotten luck! Find me at the tavern, I'll be counting ashes.",l:"Heads! Told you. Don't worry, there's no evidence.",f:"Run, run! I'll call that a draw.",d:"Your luck holds, I suppose. For now.",r:"You owe me, and I've got matches. Lucky me.",rw:"Debt burned, no evidence. A perfect job."},
 lysa:{o:"I surface, I steal, I vanish. Today I'm trying something new. A fair fight.",m:"Under the surface!",w:"Fair fight, fair loss. I'll be dripping in some tavern corner. Come and find me.",l:"And under you go. Mind the water in your boots.",f:"Vanishing? Oh, you're stealing my trick.",d:"Then I'll vanish first. Bye.",r:"You sit on my payment like a drowned king. I've come to collect.",rw:"Collected, and still dripping. A good haul."},
 ashwin:{o:"I've no patience for tall grass, and less for talk. Draw.",m:"Burn it all.",w:"Fine shooting. I'll be at the tavern, well away from the grass.",l:"Done. Go home and practise.",f:"Gone already. Saves me an arrow.",d:"Hm. Talk is cheap. Go.",r:"I missed you once in the tall grass. Now the grass is ash.",rw:"Clean shot. Let the plains burn quiet."},
 voss:{o:"One, two, three. That is how long you have before my arrow. Ready?",m:"Counting faster.",w:"Lost count. That never happens. Find me at the tavern, counting raindrops.",l:"Three seconds, as promised. Rest up.",f:"Gone before the thunder. Good timing.",d:"Then I'll count the storm alone.",r:"I missed you by one second, years ago. I've counted every second since.",rw:"Flash, count, shot. Right on time."},
 skerry:{o:"I've shot from rope bridges in a gale. Solid ground? This will be a holiday.",m:"Lightning missed again!",w:"Ha, you're steadier than any bridge. I'll be at the tavern, feet up.",l:"Down you go! Lucky for you, it's not a long drop.",f:"Off the bridge already? Fair enough.",d:"Shame. The wind was perfect.",r:"I missed you once on a swaying bridge. The bridge is steady today.",rw:"Got you. Not even a breeze to blame."},
 dorn:{o:"I sit beneath waterfalls to see who flinches first. Shall we try it with fists?",m:"I do not flinch.",w:"I flinched. Interesting. I will be at the tavern, considering it.",l:"You flinched. Most do. Sit with it.",f:"The waterfall does not chase either.",d:"Very well. The mountain is patient.",r:"Master, you taught me never to flinch. Watch me stand before your killer.",rw:"It flinched first, master. The lesson is complete."},
 hana:{o:"Catch me if you can. Nobody has, not even the brambles.",m:"Too slow, too slow!",w:"Caught! My robes are torn, and I'm so pleased. Find me in a tavern, sitting still for once.",l:"Up you get. Run with me next time instead.",f:"Oh, a race! I'll let you win this one.",d:"Then I'll run on ahead. See you there!",r:"Master, I've outrun the wind for you. Now I finish the lesson.",rw:"Done, master. And not a thread caught."},
 kori:{o:"I am calm as a frozen pond. Let us see if you can crack the ice.",m:"The thaw begins.",w:"The ice cracked. How refreshing. I will wait at the tavern, very still.",l:"Still waters. Rest in them.",f:"Flow away, then. Water always finds its way.",d:"Then I will stay frozen a while longer.",r:"Master, the thaw has come for this creature. I finish your lesson today.",rw:"The pond is frozen calm again, master."},
 senna:{o:"I've a bright idea, and my fists have a brighter one. Ready?",m:"Flash!",w:"Brilliant! Truly. I'll be at the tavern, still glowing.",l:"Too bright? It fades. Mostly.",f:"Dazzled and dashing off. I understand.",d:"Then I'll keep the flash for later.",r:"Master, your lamp went out because of this thing. I relight it now.",rw:"The temple lamp burns again, master."},
 brook:{o:"I'm on dry land, so let's be quick. A short duel, before the verse ends.",m:"Downstream we go.",w:"Well sung, all of you. I'll be at a riverside tavern, wet feet and all.",l:"The river wins again. It always does.",f:"Float away, friends! The current's kind.",d:"Then I'll sing you a farewell from the bank.",r:"One more verse for the ballad, and you're it. Mind the river.",rw:"The last verse, and it rhymes with river. Perfect."},
 dell:{o:"The forest keeps the beat. Can you keep up with it?",m:"Pick up the tempo!",w:"You kept the beat. The grove approves. I'll be drumming at the tavern.",l:"Off the beat, that time. Listen to the trees.",f:"Marching off! Good rhythm, at least.",d:"No duel? I'll drum a rest for you.",r:"One more verse, and the drums want you in it.",rw:"And the last beat lands. The grove can dance."},
 riff:{o:"My strings spark on the downstroke. Want to hear the whole song?",m:"Big downstroke!",w:"You hit every note. I'll be at the tavern, tuning up.",l:"That one was a little loud. Ears ringing?",f:"Leaving before the solo? Rude, but fine.",d:"No encore, then. Next town.",r:"One more verse for the ballad, and you're going to play it loud.",rw:"Ballad done, strings still sparking. Perfect."},
 mourne:{o:"I play lullabies for the dead. Let's see if you stay awake for this one.",m:"Hush now.",w:"Still awake, all of you. Lovely. I'll be at the tavern, playing something quieter.",l:"Sleep, little ones. Only for a moment.",f:"Away into the night. I'll play you a farewell.",d:"Then the cello waits. It is used to waiting.",r:"One more verse, a lullaby for you. Sleep well.",rw:"And the last note fades. Rest now."},
 cadence:{o:"Every festival needs a finale. Today you're the audience. Front row!",m:"Fireworks!",w:"What a finale, and I wasn't even in it! I'll be at the tavern, planning the next one.",l:"The finale was a bit much? It usually is.",f:"The audience is leaving early! How unkind.",d:"No show today? The fireworks will keep.",r:"One more verse, and the finale is you. Fireworks!",rw:"And the crowd goes wild! The ballad ends in a blaze."},
 prisma:{o:"Every note I sing leaves a rainbow and a little frost. Shall I sing to you?",m:"A clear high note.",w:"Such a lovely harmony. I'll be in a tavern, fogging the windows with song.",l:"Shh, the song is over. Let the frost melt.",f:"Leaving in the middle of an aria! I'll forgive you.",d:"Then I'll save the song for the glasshouse.",r:"One more verse, and you're it. Hold still, I hate a wobble.",rw:"The final note, and a rainbow to close it. Beautiful."},
 kaevan:{o:"You want to ride with me? Then keep up.",m:"Into the storm!",w:"You kept up. Fine. I ride with you until the storm runs out.",l:"Too slow. The steppe forgives, the storm does not. Rest, and ride again.",f:"Turning your horses already? I will circle back for you.",d:"Not yet? The storm will wait. I am less patient.",r:"Hah! I have chased you across the whole steppe. My bolt has your name on it.",rw:"One shot from the saddle. The storm is ours."},
 nikaris:{o:"Huh. They chose you.",m:"Hear the pack!",w:"The pup trusts you. The hawk trusts you. I suppose I will too.",l:"The wild is not ready for you yet. Come back softer.",f:"Running frightens them more than fighting. Come back slower.",d:"Not yet, then. The wild is patient.",r:"Wolves, hawks, all of you, I know this one's scent. It ends tonight.",rw:"The pack howls for it. Good hunt."},
 jaeson:{o:"Twin weave. You saw it too. Took me a year.",m:"Twin weave!",w:"You read the storm right. Let us see what else it says.",l:"The weave slipped. Push your glasses up and try again.",f:"Leaving the lake? The ice will hold until you return.",d:"Not ready? The storm keeps its own hours.",r:"You swallowed my stormglass and both its storms. I want them back.",rw:"Frost and lightning, home again. The weave is whole."},
 vaelith:{o:"I have written down every monster that ever ate a lamp. I have not written you yet.",m:"Turning the page.",w:"A fine page, that. I shall copy it out by candlelight.",l:"Not the ending I hoped to write. We shall draft another.",f:"Leaving mid chapter? I will hold your place.",d:"Then I will leave this page blank, for now.",r:"You ate the last page of the archive. I should very much like it back.",rw:"The archive is whole. Every page, every ending."},
 tarn:{o:"I fight like the tide. Patient. Then all at once. Ready when you are.",m:"All at once, now!",w:"You rode the wave well. Find me at the harbour tavern when you want a brawler.",l:"Tide's out for you. It comes back in, though.",f:"Swept off. Happens to the best sailors.",d:"Patient as the tide. I'll wait.",r:"You shattered my first blade at low tide. The tide's high now.",rw:"All at once, as promised. The harbour's quiet."},
 skadi:{o:"My axe has never once been warm. Let us see if you can change that.",m:"Colder still!",w:"Warm, at last. I am almost grateful. I'll wait at a tavern, near the door, where it's cold.",l:"The pass claims another. Up, before you freeze.",f:"Run down the mountain. The cold will follow.",d:"Hmph. The pass is quiet. Go.",r:"You shattered my first blade in the high pass. My axe is colder than your heart.",rw:"Frozen and finished. The pass is mine."},
 gideon:{o:"I walk into the dark so others need not. Show me you could walk beside me.",m:"Hold the light!",w:"You could walk beside me, and gladly. I'll wait at a tavern, lamp trimmed.",l:"Rest, friends. I'll carry the light back for you.",f:"Go on. I'll hold the light while you go.",d:"Then walk in the light, always.",r:"You shattered my first blade in the dark. I've brought a lamp this time.",rw:"The dark is a little smaller now."},
 terrin:{o:"I asked the stones about you nicely. They would not say. Now I ask you, less nicely.",m:"Less nicely, now.",w:"The stones were right to keep quiet. Find me at a tavern, stacking pebbles.",l:"Even stones need rest. Sit on one.",f:"Rolling away, like a pebble down a cairn.",d:"Then the stones and I will wait.",r:"You swallowed my focus, cairn stone and all. I'm asking nicely, once.",rw:"My focus, back in my palm. The cairn can rest."},
 aella:{o:"I planned a duel for today. I planned for rain too. Shall we see which arrives first?",m:"Exactly as planned.",w:"I did not plan for that. Delightful. I'll be at the tavern, revising my plans.",l:"As planned, I'm afraid. Do carry an umbrella next time.",f:"Leaving? I planned for that too.",d:"That was in my plans as well. Safe travels.",r:"You swallowed my focus, and I planned for exactly this day.",rw:"Everything as planned. Even the sunshine."},
 lucan:{o:"I catalogue stars, and lately what hides between them. Let me catalogue you.",m:"A new star rises.",w:"A bright entry for my charts. You'll find me in a tavern, looking up.",l:"Rest your eyes. The stars will wait.",f:"Off into the night? Mind what hides between the stars.",d:"Then I'll return to my charts. Clear skies.",r:"You swallowed my focus, and with it a star I named. Give it back.",rw:"My star, safe. The chapel bells will ring."},
 drift:{o:"Delivering nothing in particular today. Mind if I deliver a quick bout?",m:"Special delivery!",w:"Package lost. Fine, you win. I'll be at the tavern. Nobody checks there either.",l:"Delivered! No signature needed.",f:"Quick feet! We'd make good couriers together.",d:"Return to sender, then. Cheerio.",r:"You're sitting on my payment, and I'm here to pick up the parcel.",rw:"Parcel collected. Nobody checked."},
 sleet:{o:"My fingers are cold and my alibis are colder. Shall we make a story for them?",m:"Colder alibis.",w:"Fine work. I wasn't here, of course. You'll find me in a tavern anyway.",l:"I was never here. Remember that.",f:"You were never here either. Agreed.",d:"Then we never met. Tidy.",r:"You're sitting on my debt, and I've a cold alibi ready for this.",rw:"Collected. And I was miles away, naturally."},
 glint:{o:"Ooh, you've got shiny buckles. Win a bout and I'll only take half of them.",m:"Ooh, shiny!",w:"Fair's fair, you keep your buckles. I'll be in a tavern, polishing a spoon I found.",l:"Thank you for the buckles! Here, have one back. Half, remember.",f:"Off you go, jingling! I can hear every coin.",d:"No? I'll just admire them from here, then.",r:"You're sitting on my payment, and it's the shiniest thing in this whole realm.",rw:"Paid in full, and polished too. I'll give half away."},
 rill:{o:"I learned to shoot by missing fish. I've stopped missing. Care to see?",m:"Hooked one!",w:"Slipped the line! Well done. I'll be at a riverside tavern, lantern lit.",l:"Landed. Don't worry, I always throw them back.",f:"Off the hook! Lucky fish.",d:"Then I'll go back to the fish. They argue less.",r:"I missed you once by the lantern pools. The fish still laugh about it.",rw:"Caught at last. The fish can stop laughing."},
 corvin:{o:"I shoot from where the light does not reach. You will not see the first arrow.",m:"The rooks are watching.",w:"You found me in the dark. The rooks will gossip. I'll be in a tavern, darkest corner.",l:"The rooks saw it all. They will not tell.",f:"Into the light with you. Safer there.",d:"Then the rookery keeps its watch alone.",r:"I missed you once from the rookery wall. The rooks never let me forget.",rw:"One shot from the dark. The rooks can sleep."},
 helia:{o:"My arrows arrive a heartbeat before the sunrise. Shall we race the dawn?",m:"First light!",w:"You beat the dawn. I'll be at a tavern before sunrise, waiting.",l:"Sunrise, and you're down. It'll rise again tomorrow.",f:"Fleeing before dawn. It's coming anyway.",d:"Then I'll watch the sunrise alone.",r:"I missed you once at dawn. Today I loosed before the sun was up.",rw:"Sunrise, right on time. The watch is done."},
 thane:{o:"I stand where lightning would rather not strike. Let us see if you are bolder.",m:"Strike me, then!",w:"Bolder than lightning. Well met. I'll be at the tavern, under a good roof.",l:"The storm passes. Rise when it does.",f:"Seeking shelter. Sensible.",d:"Then the storm and I will keep watch.",r:"By my oath under the storm, you will not reach another village.",rw:"The storm settles. Oath kept."},
 galen:{o:"I guard the high roads, and nobody passes without a dance. Shall we?",m:"One, two, turn!",w:"You lead well. The pass is open to you. Find me at the tavern, swaying.",l:"You stepped on my feet. Try again.",f:"Off down the pass. Mind the switchbacks.",d:"No dance? Then pass. Carefully.",r:"On the high road I swore you'd pass no further. Let's dance.",rw:"Oath kept, and the road is clear."},
 vesper:{o:"I guard a tower nobody remembers building. You will remember this, at least.",m:"The tower stands.",w:"You will be remembered. So will I, perhaps. I'll wait in a tavern, as I wait for everything.",l:"Forgotten, for now. Rise, and be remembered later.",f:"Leaving the tower behind. Everyone does.",d:"Then go. I am used to empty roads.",r:"I swore at my tower that you would harm no one else. Someone will remember that.",rw:"Oath kept. Perhaps someone will remember my tower now."},
 noelle:{o:"My hands are cold, I'm sorry. A little trial, then something warm to drink.",m:"Bundle up, dears!",w:"Oh, well done! I'll be at the tavern with blankets. Come and warm up.",l:"Oh, poor things. Here, wrap up in this.",f:"Off you go, before the frost sets in!",d:"Of course. Mind the ice on your way.",r:"That relic belongs to the lamp keepers, and you've let it go cold. Shame on you.",rw:"Warm again in my hands. There, there."},
 ione:{o:"I argue with the thunder every morning. I've won twice. Let's argue a little, you and I.",m:"I disagree, loudly!",w:"You win the argument. Rare. I'll be at the tavern, arguing with the weather.",l:"There. Argument settled. Let me patch you up.",f:"Leaving mid argument? The thunder does that too.",d:"Then we'll argue another day.",r:"That relic was blessed in the storm chapel. I'll argue it out of your claws.",rw:"Argument won. The relic comes home."},
 ombra:{o:"I tend graves, and the living who visit them. A small trial, then I'll tend you too.",m:"Quietly now.",w:"Gently done. You'll find me at a tavern, in a quiet corner.",l:"Hush. Nobody here belongs to the graves yet.",f:"Go softly. The quiet ones are watching.",d:"Peace be with you, then.",r:"That relic belongs to the lamp keepers. Even the dead want it returned.",rw:"Returned. The graves will sleep easier."},
 carol:{o:"A frostfair song for you, and a little duel to keep warm. Ready?",m:"Skates on the ice!",w:"What a fine carol you made of that! I'll be singing at the tavern, come and join in.",l:"Slipped on the ice. Everybody does once.",f:"Skating off! Gracefully, too.",d:"Then I'll sing you a farewell carol.",r:"One more verse for the ballad, and it's a winter one. Hold still.",rw:"The final carol rings. Frostfair will hear of this."},
 aria:{o:"I took the choir on the road and only lost the roof. Shall we lose something else?",m:"Sing it to the rafters!",w:"Beautifully done. The choir and I will be at the tavern, come and hear us.",l:"Amen to that. Rise, you'll sing again.",f:"Leaving before the hymn ends! Bless you anyway.",d:"Then go with a blessing, and a tune.",r:"One more verse for the hymn, and you're it. Even without a roof.",rw:"The hymn is whole. The choir will sing it tonight."},
 mizu:{o:"Ripples first. Then the wave. Shall we begin with a ripple?",m:"Here comes the wave.",w:"The water settles. I'll wait in a tavern, by a quiet pool.",l:"Rest. Ripples fade.",f:"Flowing away. Water knows when to yield.",d:"Then I remain still.",r:"Master, this creature broke the still pond. I finish your lesson today.",rw:"The ripples are gone, master. The lesson is learned."},
 kage:{o:"I was taught that silence is a technique. You will not hear me coming.",m:"Silence.",w:"You heard me. Few do. I'll wait at a tavern, saying nothing.",l:"Quiet now. Learn from it.",f:"You leave loudly. Work on that.",d:"Silence is also an answer.",r:"Master. No more words. Only this.",rw:"Silence, master. As you taught."},
 kiyo:{o:"I bow to the dawn, then hit it with something. Shall I bow to you too?",m:"Bow, then strike!",w:"I bow to you, truly. I'll be at the tavern, practising my bows.",l:"A bow for you. You fought well.",f:"A quick bow, and gone. Very polite.",d:"Then I bow, and step aside.",r:"Master, I bow to you, and now I strike for you.",rw:"The dawn rises on your lesson, master."}
};
// a party hero with a bond history speaks up when their partner challenges you: 'challenger>speaker'
const DUEL_REPLY={
 'brann>gilda':"Careful. He swings at doors too, and loses.",'gilda>brann':"Win quick, or she'll sing about it for a year.",
 'oren>halden':"Watch his feet. He still plants them wrong.",'halden>oren':"Heels in, shoulders loose. He taught me that. Use it on him.",
 'tess>wren':"She aims with her shoulders. Watch them.",'wren>tess':"Bet you a silver she goes for the crow first.",
 'sable>pip':"Hold on to your lunch. And your purse.",'pip>sable':"Watch his hands. Then watch them again.",
 'lumen>corwin':"Mind her lamp. She walks out of every fight.",'corwin>lumen':"Be kind to his armour, please. He polishes it for hours.",
 'kael>taro':"He listens to the thunder. Listen for the boom.",'taro>kael':"He heard the storm too. Brace yourselves.",
 'fenn>frey':"He will take notes while you fight. Let him.",'frey>fenn':"She reads ice like a ledger. Find the crack before she does.",
 'mira>marisol':"She reads the tides from books. Get her wet.",'marisol>mira':"She reads the tide with her fins. Faster than my books.",
 'jun>shen':"His gloves are already on fire. Mind your eyebrows.",'shen>jun':"He bathes in ice. Hit hard, or he won't notice.",
 'vael>rook':"The dark talks to him. Don't let it talk to you.",'rook>vael':"He digs in. Do not stand where he can outlast you.",
 'lark>zephra':"She sings at the wind. I'll tell it which way to blow.",'zephra>lark':"Watch her fan, not her face.",
 'sylva>alder':"The marsh speaks well of her. Mostly in frogs.",'alder>sylva':"He'll stop halfway for tea. Let him.",
 'cass>kit':"Don't let her throw anyone. Trust me.",'kit>cass':"Watch the sky. She comes down shooting.",
 'sorrel>ember':"He takes notes on fires. Give him something to write.",'ember>sorrel':"Fascinating. Stand well back, and do take notes.",
 'dagna>brann':"Her forge runs cold, but her steel never cracks. Hit harder.",'brann>dagna':"He'll call my forge a fridge again. Prove him wrong for me.",
 'isolde>lumen':"She'll call me child again. I'm very nearly grown.",'lumen>isolde':"Gently with the little one. She glows when she is nervous.",
 'nyx>sable':"She stole my scarf. Get it back for me.",'sable>nyx':"She took my spot by the fire. Take hers.",
 'astra>vael':"Born in an eclipse. I have studied her sky my whole life.",'vael>astra':"He stares too long at the dark. Show him the light.",
 'ciro>jun':"Make him shoot. I'll kick the arrow.",'jun>ciro':"He kicks arrows. Not mine, I hope."
};
// Guild Hall recruitment challenges: what they say on the board, and when they join
const DUEL_GUILD={
 cass:{g:"I only run with fighters who read a fight before they swing. Show me you can.",j:"You read every fight like a cliff face. Lead on, I'll take the high path."},
 alder:{g:"I follow the supplies, friend. Bring me what the road needs, and I will mend the road.",j:"Healroot, hide and relics, all in order. Put the kettle on, I am coming."},
 kit:{g:"I love a big bang. Prime a foe, then set it off, and I'll come running.",j:"Five lovely booms! Count me in, and stand back a little."},
 corwin:{g:"I respect a careful captain. Bring everyone home from the dark, and I am yours.",j:"Not one fallen. That is true captaincy. My shield is yours."},
 lark:{g:"Fight with my element and I'll write a ballad about it. Every line needs a deed.",j:"My ballad has its heroes now. I'm coming with you to write the rest."},
 rook:{g:"Ten fights, no excuses. Keep standing, don't just get lucky once.",j:"Ten fights and still standing. I'll dig in beside you."},
 vex:{g:"Make the air crackle. Six reactions, and I'm yours.",j:"Static in your hair, sparks on your boots. Let's go fast!"},
 sorrel:{g:"I want to see what you do with a marked beast. Fight two, and I'll take notes.",j:"Two bounties, beautifully done. My candles are yours."},
 frey:{g:"Ice cracks where it is weakest. Show me you can find the crack in anything.",j:"You read the seams like ice. I will stand watch for you."},
 nyx:{g:"I trust what I see with my own eyes. Fight with my element, and I'll watch.",j:"I've seen enough. I'll come along, and keep my paws off your purse. Mostly."},
 isak:{g:"I follow captains who are still standing at the end. Win eight, and I'll know.",j:"Eight fights, and you're all still standing. My oath is yours."},
 lorcan:{g:"There is a seam in anything, even stone. Find it in your foes, and I will follow.",j:"You found every seam. The stone bends to you, and so do I."},
 hollis:{g:"I keep count of the ones who got home. Bring everyone home from the dark, five times.",j:"Five times, nobody lost. You keep good count. I'll walk with you."},
 senna:{g:"I want a lot of flash for my trouble. Set off seven reactions and I'm yours.",j:"Seven dazzling bursts! My fists are yours."}
};
// ----- fallback: a hero with no lines still gets their own, from name, class, element and trait -----
const DL_FB_CLS={warrior:['my blade','swing'],knight:['my shield','hold'],mage:['my spells','cast'],healer:['my hands','mend'],thief:['my quick fingers','slip past'],archer:['my bow','loose'],monk:['my fists','strike'],bard:['my song','play'],sniper:['my long shot','aim'],druid:['the wild','call'],archmage:['my old sigils','weave'],chronicler:['my quill','write']};
const DL_FB_EL={fire:'the flame',water:'the tide',earth:'the stone',wind:'the wind',ice:'the frost',lightning:'the storm',light:'the dawn',shadow:'the dark'};
function dlFallback(id,k){const t=TPL[id]||{n:id,cls:'warrior',el:['light']},n=t.n,C=DL_FB_CLS[t.cls]||DL_FB_CLS.warrior,e=DL_FB_EL[(t.el||[])[0]]||'the road',tr=(typeof CW_TRAIT!=='undefined'&&CW_TRAIT[t.trait])||'ready';
  const L={o:`They call me ${n}, and ${e} walks with me. One fair bout, ${C[0]} against yours?`,m:`${e.replace(/^the /,'').replace(/^./,c=>c.toUpperCase())}, with me!`,
    w:`${n} bows to you. Find me at a tavern when ${e} brings you near.`,l:`${n} has won this one. Rest, and let ${e} mend you.`,
    f:`Gone already? ${n} will ${C[1]} another day.`,d:`Another time, then. ${n} and ${e} can wait.`,
    r:`${n} has waited a long time for you. ${C[0].replace(/^my/,'My')} and ${e} are ready.`,rw:`It is finished. ${n} can rest easy now.`};
  return L[k]||L.o;}
// pick a line: own lines first, else the fallback. Variants are chosen from the journey seed only (no game RNG).
function dlSeed(){try{return String(G&&G.run&&G.run.seed||0);}catch(e){return '0';}}
function dlLine(id,k){const L=DUEL_LINES[id];let v=L&&L[k];if(Array.isArray(v))v=v.length?v[hashS(dlSeed()+':'+id+':'+k)%v.length]:null;return v||dlFallback(id,k);}
function dlName(id){return (TPL[id]&&TPL[id].n)||id;}
function dlQuote(id,k){return `${dlName(id)}: "${dlLine(id,k)}"`;}
// a bond partner in your six who speaks up when the challenger is their old friend
function dlReply(hero){try{const P=(G&&G.party)||[];for(const id of P){const s=DUEL_REPLY[hero+'>'+id];if(s)return {by:id,text:s};}}catch(e){}return null;}
function dlToast(m,ms){toast(m);try{const t=document.getElementById('toast');clearTimeout(toast.h);toast.h=setTimeout(()=>{if(t)t.className='';},ms||4600);}catch(e){}}
function dlSay(id,k,cls){return `<p class="dl-say ${cls||''}"><b>${esc(dlName(id))}:</b> "${esc(dlLine(id,k))}"</p>`;}
// who is challenging in the current battle, and in which context
function dlBattleWho(spec){if(!spec)return null;if(spec.ce&&spec.ce.mode==='duel')return {id:spec.ce.hero,ctx:'duel'};if(spec.kind==='legend'&&TPL[spec.hero])return {id:spec.hero,ctx:'legend'};return null;}
// ----- 1. the road duel: the opening, the bond reply, the decline -----
{const cs1=ceStart;ceStart=function(m,hero,type){const r=cs1.apply(this,arguments);try{const ev=V.modal&&V.modal.type==='cev'&&V.modal.ev;
  if(ev&&ev.hero===hero&&ev.type==='duel'){const intro=cwIntro(hero,cwTheme(m),!!m.cave);ev.text=`${intro}, steps into your path and sizes you up. "${dlLine(hero,'o')}"`;ev.reply=dlReply(hero);ev.dl=1;render();}}catch(e){}return r;};}
function cwDecline(hero){return dlQuote(hero,'d');}
{const vm1=vModal;vModal=function(m){let h=vm1.apply(this,arguments);try{
  if(m&&m.type==='cev'&&m.ev&&m.ev.reply&&typeof h==='string'){const R=m.ev.reply;h=h.replace('</p></div>',`</p></div><p class="dl-rep"><b>${esc(dlName(R.by))}:</b> "${esc(R.text)}"</p>`);}
  else if(m&&m.type==='lose'&&typeof h==='string'&&typeof B!=='undefined'&&B){const w=dlBattleWho(B.spec);if(w)h=h.replace('</p>','</p>'+dlSay(w.id,'l'));}
  else if(m&&m.type==='elite'&&m.b&&m.b.personal&&typeof h==='string'&&TPL[m.b.personal])h=h.replace('</p>','</p>'+dlSay(m.b.personal,'r','dl-rival'));
}catch(e){}return h;};}
// ----- 2. in the duel: their own shout at half health (the banner and the log) -----
{const ef1=encounterFoes;encounterFoes=function(spec){const out=ef1.apply(this,arguments);try{if(spec&&spec.kind==='duel'&&spec.hero&&out&&out[0]&&out[0].phase)out[0].phase.say=`${dlName(spec.hero)}: "${dlLine(spec.hero,'m')}"`;}catch(e){}return out;};}
// ----- 3. the result: they lose (rewards screen), the rival falls -----
{const cw2=challengeWin;challengeWin=function(spec,info){const r=cw2.apply(this,arguments);try{
  if(spec&&spec.ce&&spec.ce.mode==='duel'&&info&&info.legendKind==='duel')info.legend=dlQuote(spec.ce.hero,'w');
  if(spec&&spec.kind==='elite'&&spec.bounty&&spec.bounty.personal&&info&&info.personal)info.dlRival=spec.bounty.personal;}catch(e){}return r;};}
{const rj=rsJoin;rsJoin=function(i){let h=rj.apply(this,arguments);try{if(i&&i.dlRival&&TPL[i.dlRival]){const row=`<div class="rs-join dl-rw"><b>${esc(dlName(i.dlRival))}</b><span>"${esc(dlLine(i.dlRival,'rw'))}"</span></div>`;
  h=h?h.replace(/<\/div>$/,row+'</div>'):`<div class="rs-sec">${row}</div>`;}}catch(e){}return h;};}
// ----- 4. running from the duel (or from Kaevan's ride, or Nikaris's beasts) -----
{const fb1=finishBattle;finishBattle=function(how){const w=(how==='fled'&&typeof B!=='undefined'&&B)?dlBattleWho(B.spec):null;const r=fb1.apply(this,arguments);
  try{if(w){const pre=w.id==='nikaris'?'A voice in the dark: ':'';dlToast(pre+dlQuote(w.id,'f'));}}catch(e){}return r;};}
// ----- 5. legends: Kaevan's ride opens with his own line, and every legend joins with theirs -----
{const lt=legendTalk;legendTalk=function(a){const r=lt.apply(this,arguments);try{const m=V.modal;if(m&&m.type==='legendEvt'&&m.hero==='kaevan'&&!m.join){
  m.text=`Dusk turns the grass to copper. A rider on a black horse circles you once, crossbow resting on his knee, mustache magnificent against the storm. "${dlLine('kaevan','o')}" His hawks scream overhead.`;render();}}catch(e){}return r;};}
{const lj=legendJoin;legendJoin=function(id,info){const had=!!(G&&G.roster[id]);const r=lj.apply(this,arguments);try{if(!had&&G.roster[id]&&DUEL_LINES[id]){const line=`"${dlLine(id,'w')}"`;
  if(info&&info.legend)info.legend=`${TPL[id].title} joins you. ${line}`;
  else if(V.modal&&V.modal.type==='story')V.modal.text=`${line}\n\n${TPL[id].n} joins your roster${G.party.includes(id)?' and your six':''}.`;}}catch(e){}return r;};}
// ----- 6. Guild Hall recruitment challenges: their own words on the board and when they join -----
{const ct=challText;challText=function(c,st){const s=ct.apply(this,arguments);try{const g=DUEL_GUILD[c.hero];if(g&&g.g)return s+` ${TPL[c.hero].n}: "${g.g}"`;}catch(e){}return s;};}
{const cc=ACT.chClaim;ACT.chClaim=function(h){const was=!!(G&&G.roster[h]);const r=cc.apply(this,arguments);try{const g=DUEL_GUILD[h];if(!was&&G.roster[h]&&g&&g.j)dlToast(`${TPL[h].n} joins you: "${g.j}"${G.party.includes(h)?'':' Add them to your six in town.'}`);}catch(e){}return r;};}
